/**
 * L1 · 最裸的循环
 *
 * 一个 AI coding agent 的核心：把工具结果反复喂回给模型，直到模型不再请求工具。
 *
 *     用户提问 ──> 模型 ──> 请求工具? ──是──> 执行工具 ──> 结果写回对话
 *                   ^                                            |
 *                   └────────────────────────────────────────────┘
 *
 * 这一课刻意从简，留下三处局限；后面三根支柱(L2 插件 / L3 事件日志 / L4 KV缓存)逐一解决：
 *   ❶ 能力与循环耦合：bash 直接写在循环旁    → L2 拆成插件
 *   ❷ 对话是可变数组 history，可被任意修改   → L3 换成 append-only 事件日志
 *   ❸ 每步都重发整个 history                 → L4 从 KV 缓存角度审视
 */

import OpenAI from "openai"
import type { ChatCompletionMessageParam, ChatCompletionTool } from "openai/resources/chat/completions"
import { execSync } from "node:child_process"
import * as readline from "node:readline/promises"
import "dotenv/config"

// DeepSeek API 与 OpenAI 兼容，故用 openai SDK 指向 DeepSeek 地址
const client = new OpenAI({
  apiKey: process.env.DEEPSEEK_API_KEY,
  baseURL: process.env.DEEPSEEK_BASE_URL ?? "https://api.deepseek.com",
})
const MODEL = process.env.MODEL_ID ?? "deepseek-chat"

const SYSTEM = `You are a coding agent working in ${process.cwd()}. Use the bash tool to accomplish tasks. Act, don't over-explain.`

const TOOLS: ChatCompletionTool[] = [
  {
    type: "function",
    function: {
      name: "bash",
      description: "Run a shell command and return its output.",
      parameters: {
        type: "object",
        properties: { command: { type: "string", description: "the shell command" } },
        required: ["command"],
      },
    },
  },
]

function runBash(command: string): string {
  // 最小安全护栏，L5 升级为完整权限管线
  const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"]
  if (dangerous.some((d) => command.includes(d))) return "Error: 危险命令已拦截"

  try {
    const out = execSync(command, { encoding: "utf8", timeout: 120_000, stdio: ["ignore", "pipe", "pipe"] })
    return out.trim().slice(0, 50_000) || "(无输出)"
  } catch (e: any) {
    // 命令退出码非 0 时 execSync 抛异常，但 stdout/stderr 仍需返回给模型
    const out = ((e.stdout ?? "") + (e.stderr ?? "")).trim()
    return out ? out.slice(0, 50_000) : `Error: ${e.message}`
  }
}

async function agentLoop(history: ChatCompletionMessageParam[]) {
  while (true) {
    const res = await client.chat.completions.create({
      model: MODEL,
      messages: history,
      tools: TOOLS,
      max_tokens: 4000,
    })

    const msg = res.choices[0].message
    history.push(msg)

    // 模型未请求工具，本轮结束
    if (!msg.tool_calls || msg.tool_calls.length === 0) return

    for (const call of msg.tool_calls) {
      // arguments 是模型生成的 JSON 字符串，形状运行时才定：这是类型系统管不到的边界
      const args = JSON.parse(call.function.arguments) as { command: string }
      console.log(`\x1b[33m$ ${args.command}\x1b[0m`)
      const output = runBash(args.command)
      console.log(output.slice(0, 300))
      history.push({ role: "tool", tool_call_id: call.id, content: output })
    }
  }
}

const rl = readline.createInterface({ input: process.stdin, output: process.stdout })
const history: ChatCompletionMessageParam[] = [{ role: "system", content: SYSTEM }]

console.log("L1 · 最裸的循环")
console.log("输入问题回车发送；输入 q 退出。\n")

while (true) {
  const q = await rl.question("\x1b[36mL1 >> \x1b[0m")
  if (["q", "exit", ""].includes(q.trim().toLowerCase())) break

  history.push({ role: "user", content: q })
  await agentLoop(history)

  const last = history[history.length - 1]
  if (last.role === "assistant" && typeof last.content === "string") console.log(last.content)
  console.log()
}
rl.close()

/**
 * L2 · 一切皆插件 (支柱 P1)
 *
 * 解决 L1 局限 ❶：能力与循环耦合。做法是把循环收缩到最小——只负责驱动流程并在
 * 固定扩展点触发事件；工具等能力全部外置为插件，通过共享上下文与事件系统接入。
 *
 * 两个基础设施：
 *   1) 共享上下文 ctx —— 服务(能力)注册于此，插件间通过它互相获取
 *   2) 事件系统    —— 循环在固定点触发事件，插件监听并介入
 *
 * 事件分两类：
 *   emit      通知型：仅广播，监听者无法改变主流程（如「工具已执行」）
 *   waterfall 瀑布型：依次传递，每个监听器可改写内容后再传给下一个（如「请求前修改消息」）
 */

import OpenAI from "openai"
import type { ChatCompletionMessageParam, ChatCompletionTool } from "openai/resources/chat/completions"
import { execSync } from "node:child_process"
import * as readline from "node:readline/promises"
import "dotenv/config"

const client = new OpenAI({
  apiKey: process.env.DEEPSEEK_API_KEY,
  baseURL: process.env.DEEPSEEK_BASE_URL ?? "https://api.deepseek.com",
})
const MODEL = process.env.MODEL_ID ?? "deepseek-chat"
const SYSTEM = `You are a coding agent working in ${process.cwd()}. Use tools to accomplish tasks. Act, don't over-explain.`

// ═══════════════════════════════════════════════════════════════
//  迷你框架：共享上下文 + 事件系统（后续每课原样复制）
//
//  框架内部使用 any 类型是刻意的取舍。若要精确类型需为 Ctx 引入泛型与事件映射表，
//  会偏离本课主题。真实 DeepSeek Harness 用泛型换取了完整类型安全。
// ═══════════════════════════════════════════════════════════════
type NextFn = () => Promise<any>
type Listener = (payload: any, next: NextFn) => Promise<any> | any

class Ctx {
  services: Record<string, any> = {}
  private listeners: Record<string, Listener[]> = {}

  provide(name: string, service: any) {
    this.services[name] = service
  }

  // 返回注销函数，便于插件卸载时清理自身监听
  on(event: string, fn: Listener): () => void {
    ;(this.listeners[event] ??= []).push(fn)
    return () => {
      const arr = this.listeners[event]!
      arr.splice(arr.indexOf(fn), 1)
    }
  }

  async emit(event: string, payload: any): Promise<void> {
    for (const fn of this.listeners[event] ?? []) await fn(payload, async () => {})
  }

  // base 是链条走到末端时的默认返回值；每个监听器调用 next() 取得下游结果后可再加工
  async waterfall(event: string, payload: any, base: NextFn): Promise<any> {
    const chain = this.listeners[event] ?? []
    let i = 0
    const next: NextFn = () =>
      i < chain.length ? Promise.resolve(chain[i++](payload, next)) : base()
    return next()
  }
}

// ═══════════════════════════════════════════════════════════════
//  服务：工具注册表（工具改为注册接入，不再内联于循环）
// ═══════════════════════════════════════════════════════════════
function createToolRegistry() {
  const tools: Record<string, { schema: any; run: (args: any) => string }> = {}
  return {
    register(name: string, schema: any, run: (args: any) => string) {
      tools[name] = { schema, run }
    },
    schemas(): ChatCompletionTool[] {
      return Object.entries(tools).map(([name, t]) => ({
        type: "function",
        function: { name, ...t.schema },
      }))
    },
    execute(name: string, args: any): string {
      const t = tools[name]
      if (!t) return `Error: 未知工具 ${name}`
      return t.run(args)
    },
  }
}

// ═══════════════════════════════════════════════════════════════
//  插件 ①：bash —— 将 bash 注册为工具
// ═══════════════════════════════════════════════════════════════
function bashPlugin(ctx: Ctx) {
  function runBash(command: string): string {
    const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"]
    if (dangerous.some((d) => command.includes(d))) return "Error: 危险命令已拦截"
    try {
      const out = execSync(command, { encoding: "utf8", timeout: 120_000, stdio: ["ignore", "pipe", "pipe"] })
      return out.trim().slice(0, 50_000) || "(无输出)"
    } catch (e: any) {
      const out = ((e.stdout ?? "") + (e.stderr ?? "")).trim()
      return out ? out.slice(0, 50_000) : `Error: ${e.message}`
    }
  }
  ctx.services.tools.register(
    "bash",
    {
      description: "Run a shell command and return its output.",
      parameters: {
        type: "object",
        properties: { command: { type: "string", description: "the shell command" } },
        required: ["command"],
      },
    },
    // 显式标注参数类型：经由 any 的 ctx.services 取到的 register 无上下文类型，strict 下需自行标注
    (args: { command: string }) => runBash(args.command),
  )
}

// ═══════════════════════════════════════════════════════════════
//  插件 ②：log —— 纯观察者，仅监听「工具已执行」，不介入主流程
//  它不改动循环与 bash，证明新增能力无需修改主干
// ═══════════════════════════════════════════════════════════════
function logPlugin(ctx: Ctx) {
  ctx.on("tools/result", ({ exec }) => {
    console.log(`\x1b[90m  [log] 工具 "${exec.name}" 执行完毕\x1b[0m`)
  })
}

// ═══════════════════════════════════════════════════════════════
//  精简循环：只触发事件、调用服务，不含任何具体能力
// ═══════════════════════════════════════════════════════════════
async function step(ctx: Ctx, history: ChatCompletionMessageParam[]): Promise<boolean> {
  // agent/pre-step 瀑布：请求前的统一介入点。当前无监听器，base 原样返回 history；L4 起在此注入上下文
  const messages: ChatCompletionMessageParam[] = await ctx.waterfall("agent/pre-step", { history }, async () => history)

  const res = await client.chat.completions.create({
    model: MODEL,
    messages,
    tools: ctx.services.tools.schemas(),
    max_tokens: 4000,
  })
  const msg = res.choices[0].message
  history.push(msg)
  if (!msg.tool_calls?.length) return false

  for (const call of msg.tool_calls) {
    const args = JSON.parse(call.function.arguments) as { command: string }
    console.log(`\x1b[33m$ ${args.command ?? JSON.stringify(args)}\x1b[0m`)
    const output: string = ctx.services.tools.execute(call.function.name, args)
    console.log(output.slice(0, 300))
    history.push({ role: "tool", tool_call_id: call.id, content: output })
    await ctx.emit("tools/result", { exec: { name: call.function.name, args }, result: { content: output } })
  }
  return true
}

async function runAgent(ctx: Ctx, history: ChatCompletionMessageParam[]) {
  while (await step(ctx, history)) {}
}

// ═══════════════════════════════════════════════════════════════
//  组装：新增/移除能力只改动这几行，循环不动
// ═══════════════════════════════════════════════════════════════
const ctx = new Ctx()
ctx.provide("tools", createToolRegistry())
bashPlugin(ctx)
logPlugin(ctx) // 注释掉此行可验证：移除能力无需改动循环

const rl = readline.createInterface({ input: process.stdin, output: process.stdout })
const history: ChatCompletionMessageParam[] = [{ role: "system", content: SYSTEM }]

console.log("L2 · 一切皆插件")
console.log("输入问题回车发送；输入 q 退出。\n")

while (true) {
  const q = await rl.question("\x1b[36mL2 >> \x1b[0m")
  if (["q", "exit", ""].includes(q.trim().toLowerCase())) break
  history.push({ role: "user", content: q })
  await runAgent(ctx, history)
  const last = history[history.length - 1]
  if (last.role === "assistant" && typeof last.content === "string") console.log(last.content)
  console.log()
}
rl.close()

/**
 * L3 · Session Log 是唯一真相 (支柱 P2)
 *
 * 解决 L1 局限 ❷：对话是可变数组，可被任意修改、进程结束即丢失、无法确定性重放。
 * 做法：用一条 append-only 事件日志承载对话，模型看到的消息由日志派生。
 *
 *   • 事件日志 events[]：记录全部事件——用户消息、模型回复、工具结果，以及 turn 边界。仅追加，不修改。
 *   • surface：日志中「进入对话」的事件子集，是一个有序的 seq 列表。turn 边界这类事件不进入 surface。
 *
 * deriveMessages() 按 surface 列出的 seq 依次取出对应事件、投影为模型消息。
 * 这一分离是后续能力的地基：压缩(L6)只需追加一条 replace 事件改写 surface，原始日志不删；
 * 崩溃恢复只需重放日志即可精确重建。
 */

import OpenAI from "openai"
import type { ChatCompletionMessageParam, ChatCompletionTool } from "openai/resources/chat/completions"
import { execSync } from "node:child_process"
import * as readline from "node:readline/promises"
import "dotenv/config"

const client = new OpenAI({
  apiKey: process.env.DEEPSEEK_API_KEY,
  baseURL: process.env.DEEPSEEK_BASE_URL ?? "https://api.deepseek.com",
})
const MODEL = process.env.MODEL_ID ?? "deepseek-chat"
const SYSTEM = `You are a coding agent working in ${process.cwd()}. Use tools to accomplish tasks. Act, don't over-explain.`

// ═══════════════════════════════════════════════════════════════
//  迷你框架（同 L2）
// ═══════════════════════════════════════════════════════════════
type NextFn = () => Promise<any>
type Listener = (payload: any, next: NextFn) => Promise<any> | any

class Ctx {
  services: Record<string, any> = {}
  private listeners: Record<string, Listener[]> = {}
  provide(name: string, service: any) {
    this.services[name] = service
  }
  on(event: string, fn: Listener): () => void {
    ;(this.listeners[event] ??= []).push(fn)
    return () => {
      const arr = this.listeners[event]!
      arr.splice(arr.indexOf(fn), 1)
    }
  }
  async emit(event: string, payload: any): Promise<void> {
    for (const fn of this.listeners[event] ?? []) await fn(payload, async () => {})
  }
  async waterfall(event: string, payload: any, base: NextFn): Promise<any> {
    const chain = this.listeners[event] ?? []
    let i = 0
    const next: NextFn = () =>
      i < chain.length ? Promise.resolve(chain[i++](payload, next)) : base()
    return next()
  }
}

// ═══════════════════════════════════════════════════════════════
//  ★ 本课主角：Session —— append-only 事件日志
// ═══════════════════════════════════════════════════════════════
type SurfaceType = "user/message" | "assistant/message" | "tool/result"
interface SessionEvent {
  seq: number
  type: SurfaceType | "turn/start" | "turn/end"
  data: any
}

class Session {
  events: SessionEvent[] = []
  surface: number[] = [] // 进入对话的事件 seq，有序
  private seqCounter = 0

  // onSurface 决定该事件是否进入对话。L3 仅支持追加；replace 在 L6 引入
  append(type: SessionEvent["type"], data: any, onSurface = false): SessionEvent {
    const event: SessionEvent = { seq: this.seqCounter++, type, data }
    this.events.push(event)
    if (onSurface) this.surface.push(event.seq)
    return event
  }

  deriveMessages(): ChatCompletionMessageParam[] {
    // seq 等于事件在 events 中的下标（events 只增，seq 与 push 同步自增），故可直接索引
    return this.surface.map((seq) => {
      const e = this.events[seq]
      switch (e.type) {
        case "user/message":
          return { role: "user", content: e.data.content }
        case "assistant/message":
          return e.data.message // 存入的是模型返回的完整消息，含 content 与 tool_calls
        case "tool/result":
          return { role: "tool", tool_call_id: e.data.tool_call_id, content: e.data.content }
        default:
          throw new Error(`非 surface 事件不应出现在 surface 列表中: ${e.type}`)
      }
    })
  }
}

// ═══════════════════════════════════════════════════════════════
//  工具注册表 + bash/log 插件（同 L2）
// ═══════════════════════════════════════════════════════════════
function createToolRegistry() {
  const tools: Record<string, { schema: any; run: (args: any) => string }> = {}
  return {
    register(name: string, schema: any, run: (args: any) => string) {
      tools[name] = { schema, run }
    },
    schemas(): ChatCompletionTool[] {
      return Object.entries(tools).map(([name, t]) => ({
        type: "function",
        function: { name, ...t.schema },
      }))
    },
    execute(name: string, args: any): string {
      const t = tools[name]
      if (!t) return `Error: 未知工具 ${name}`
      return t.run(args)
    },
  }
}

function bashPlugin(ctx: Ctx) {
  function runBash(command: string): string {
    const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"]
    if (dangerous.some((d) => command.includes(d))) return "Error: 危险命令已拦截"
    try {
      const out = execSync(command, { encoding: "utf8", timeout: 120_000, stdio: ["ignore", "pipe", "pipe"] })
      return out.trim().slice(0, 50_000) || "(无输出)"
    } catch (e: any) {
      const out = ((e.stdout ?? "") + (e.stderr ?? "")).trim()
      return out ? out.slice(0, 50_000) : `Error: ${e.message}`
    }
  }
  ctx.services.tools.register(
    "bash",
    {
      description: "Run a shell command and return its output.",
      parameters: {
        type: "object",
        properties: { command: { type: "string", description: "the shell command" } },
        required: ["command"],
      },
    },
    (args: { command: string }) => runBash(args.command),
  )
}

function logPlugin(ctx: Ctx) {
  ctx.on("tools/result", ({ exec }) => {
    console.log(`\x1b[90m  [log] 工具 "${exec.name}" 执行完毕\x1b[0m`)
  })
}

// ═══════════════════════════════════════════════════════════════
//  循环：改为向 Session 追加事件，不再直接改数组
// ═══════════════════════════════════════════════════════════════
async function step(ctx: Ctx, session: Session): Promise<boolean> {
  // SYSTEM 每次组装、不写入日志：它属于请求信封，不属于对话历史
  const messages: ChatCompletionMessageParam[] = await ctx.waterfall("agent/pre-step", { session }, async () => [
    { role: "system", content: SYSTEM },
    ...session.deriveMessages(),
  ])

  const res = await client.chat.completions.create({
    model: MODEL,
    messages,
    tools: ctx.services.tools.schemas(),
    max_tokens: 4000,
  })
  const msg = res.choices[0].message
  session.append("assistant/message", { message: msg }, true)
  if (!msg.tool_calls?.length) return false

  for (const call of msg.tool_calls) {
    const args = JSON.parse(call.function.arguments) as { command: string }
    console.log(`\x1b[33m$ ${args.command ?? JSON.stringify(args)}\x1b[0m`)
    const output: string = ctx.services.tools.execute(call.function.name, args)
    console.log(output.slice(0, 300))
    session.append("tool/result", { tool_call_id: call.id, content: output }, true)
    await ctx.emit("tools/result", { exec: { name: call.function.name, args }, result: { content: output } })
  }
  return true
}

async function runTurn(ctx: Ctx, session: Session, userText: string) {
  session.append("turn/start", { text: userText }) // 边界事件，不进入 surface
  session.append("user/message", { content: userText }, true)
  while (await step(ctx, session)) {}
  session.append("turn/end", {})
}

// ═══════════════════════════════════════════════════════════════
//  组装
// ═══════════════════════════════════════════════════════════════
const ctx = new Ctx()
ctx.provide("tools", createToolRegistry())
bashPlugin(ctx)
logPlugin(ctx)

const session = new Session()

const rl = readline.createInterface({ input: process.stdin, output: process.stdout })

console.log("L3 · Session Log 是唯一真相")
console.log("命令：/log 打印事件日志 | /surface 打印 surface | q 退出\n")

while (true) {
  const q = await rl.question("\x1b[36mL3 >> \x1b[0m")
  const cmd = q.trim().toLowerCase()
  if (["q", "exit", ""].includes(cmd)) break

  if (cmd === "/log") {
    console.log("\x1b[90m── 事件日志（记录全部事件）──\x1b[0m")
    for (const e of session.events) {
      const on = session.surface.includes(e.seq) ? "\x1b[32m[在 surface]\x1b[0m" : "\x1b[90m[仅日志]\x1b[0m"
      console.log(`  seq ${String(e.seq).padStart(2)} ${e.type.padEnd(18)} ${on}`)
    }
    console.log()
    continue
  }
  if (cmd === "/surface") {
    console.log(`\x1b[90msurface（模型看到的 seq 顺序）:\x1b[0m [${session.surface.join(", ")}]\n`)
    continue
  }

  await runTurn(ctx, session, q)
  // 末尾是 turn/end，其前一条为本轮最后的 assistant 消息
  const last = session.events[session.events.length - 2]
  if (last?.type === "assistant/message" && typeof last.data.message.content === "string") {
    console.log(last.data.message.content)
  }
  console.log()
}
rl.close()

/**
 * L4 · 对 KV Cache 敏感 (支柱 P3)
 *
 * 服务端前缀缓存的规则：从首个 token 起逐字节一致的前缀才能命中、免于重算；
 * 一旦某位置改变，其后全部失效。
 *
 * 由此得出上下文注入的纪律：一律追加到末尾(append-only)，不修改中间。
 *
 * 本课：
 *   1) 接入第一个上下文注入插件（在 agent/pre-step 向请求注入「当前时间」）
 *   2) 打印 DeepSeek 返回的缓存命中 token 数
 *   3) 用 /append 与 /prepend 对比同一注入放在末尾与开头对缓存命中的影响
 */

import OpenAI from "openai"
import type { ChatCompletionMessageParam, ChatCompletionTool } from "openai/resources/chat/completions"
import { execSync } from "node:child_process"
import * as readline from "node:readline/promises"
import "dotenv/config"

const client = new OpenAI({
  apiKey: process.env.DEEPSEEK_API_KEY,
  baseURL: process.env.DEEPSEEK_BASE_URL ?? "https://api.deepseek.com",
})
const MODEL = process.env.MODEL_ID ?? "deepseek-chat"

// 系统提示写长一些，使前缀稳定超过 DeepSeek 缓存的最小块(约 64 tokens)，便于观察缓存
const SYSTEM =
  `You are a meticulous coding agent working in ${process.cwd()}. ` +
  `Use the available tools to accomplish tasks. When asked to look something up, ` +
  `call a tool and wait for its result before answering. Never invent tool output. ` +
  `Answer concisely in the user's language. Act, don't over-explain.`

// ═══════════════════════════════════════════════════════════════
//  迷你框架（同 L2/L3）
// ═══════════════════════════════════════════════════════════════
type NextFn = () => Promise<any>
type Listener = (payload: any, next: NextFn) => Promise<any> | any

class Ctx {
  services: Record<string, any> = {}
  private listeners: Record<string, Listener[]> = {}
  provide(name: string, service: any) {
    this.services[name] = service
  }
  on(event: string, fn: Listener): () => void {
    ;(this.listeners[event] ??= []).push(fn)
    return () => {
      const arr = this.listeners[event]!
      arr.splice(arr.indexOf(fn), 1)
    }
  }
  async emit(event: string, payload: any): Promise<void> {
    for (const fn of this.listeners[event] ?? []) await fn(payload, async () => {})
  }
  async waterfall(event: string, payload: any, base: NextFn): Promise<any> {
    const chain = this.listeners[event] ?? []
    let i = 0
    const next: NextFn = () =>
      i < chain.length ? Promise.resolve(chain[i++](payload, next)) : base()
    return next()
  }
}

// ═══════════════════════════════════════════════════════════════
//  Session（同 L3）
// ═══════════════════════════════════════════════════════════════
type SurfaceType = "user/message" | "assistant/message" | "tool/result"
interface SessionEvent {
  seq: number
  type: SurfaceType | "turn/start" | "turn/end"
  data: any
}

class Session {
  events: SessionEvent[] = []
  surface: number[] = []
  private seqCounter = 0

  append(type: SessionEvent["type"], data: any, onSurface = false): SessionEvent {
    const event: SessionEvent = { seq: this.seqCounter++, type, data }
    this.events.push(event)
    if (onSurface) this.surface.push(event.seq)
    return event
  }

  deriveMessages(): ChatCompletionMessageParam[] {
    // seq 等于事件在 events 中的下标（events 只增，seq 与 push 同步自增），故可直接索引
    return this.surface.map((seq) => {
      const e = this.events[seq]
      switch (e.type) {
        case "user/message":
          return { role: "user", content: e.data.content }
        case "assistant/message":
          return e.data.message
        case "tool/result":
          return { role: "tool", tool_call_id: e.data.tool_call_id, content: e.data.content }
        default:
          throw new Error(`非 surface 事件不应出现在 surface 列表中: ${e.type}`)
      }
    })
  }
}

// ═══════════════════════════════════════════════════════════════
//  工具注册表 + bash/log 插件（同 L3）
// ═══════════════════════════════════════════════════════════════
function createToolRegistry() {
  const tools: Record<string, { schema: any; run: (args: any) => string }> = {}
  return {
    register(name: string, schema: any, run: (args: any) => string) {
      tools[name] = { schema, run }
    },
    schemas(): ChatCompletionTool[] {
      return Object.entries(tools).map(([name, t]) => ({
        type: "function",
        function: { name, ...t.schema },
      }))
    },
    execute(name: string, args: any): string {
      const t = tools[name]
      if (!t) return `Error: 未知工具 ${name}`
      return t.run(args)
    },
  }
}

function bashPlugin(ctx: Ctx) {
  function runBash(command: string): string {
    const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"]
    if (dangerous.some((d) => command.includes(d))) return "Error: 危险命令已拦截"
    try {
      const out = execSync(command, { encoding: "utf8", timeout: 120_000, stdio: ["ignore", "pipe", "pipe"] })
      return out.trim().slice(0, 50_000) || "(无输出)"
    } catch (e: any) {
      const out = ((e.stdout ?? "") + (e.stderr ?? "")).trim()
      return out ? out.slice(0, 50_000) : `Error: ${e.message}`
    }
  }
  ctx.services.tools.register(
    "bash",
    {
      description: "Run a shell command and return its output.",
      parameters: {
        type: "object",
        properties: { command: { type: "string", description: "the shell command" } },
        required: ["command"],
      },
    },
    (args: { command: string }) => runBash(args.command),
  )
}

// ═══════════════════════════════════════════════════════════════
//  ★ 本课新增：上下文注入插件（time-context 的最小形态）
//  注入的是每轮都不同的值（当前时间），因此注入位置直接决定缓存命中：
//    append  放末尾——其前的 [system + 对话] 前缀不变，命中
//    prepend 放开头——改变前缀，其后全部失效
// ═══════════════════════════════════════════════════════════════
let injectMode: "append" | "prepend" = "append"

function timeContextPlugin(ctx: Ctx) {
  ctx.on("agent/pre-step", async (_payload, next) => {
    const messages: ChatCompletionMessageParam[] = await next()
    const ctxMsg: ChatCompletionMessageParam = {
      role: "user",
      content: `[上下文] 当前时间：${new Date().toISOString()}`,
    }
    return injectMode === "append"
      ? [...messages, ctxMsg]
      : [messages[0], ctxMsg, ...messages.slice(1)] // system 之后、对话之前
  })
}

function logPlugin(ctx: Ctx) {
  ctx.on("tools/result", ({ exec }) => {
    console.log(`\x1b[90m  [log] 工具 "${exec.name}" 执行完毕\x1b[0m`)
  })
}

// ═══════════════════════════════════════════════════════════════
//  循环：新增读取并打印缓存命中数
// ═══════════════════════════════════════════════════════════════
async function step(ctx: Ctx, session: Session): Promise<boolean> {
  const messages: ChatCompletionMessageParam[] = await ctx.waterfall("agent/pre-step", { session }, async () => [
    { role: "system", content: SYSTEM },
    ...session.deriveMessages(),
  ])

  const res = await client.chat.completions.create({
    model: MODEL,
    messages,
    tools: ctx.services.tools.schemas(),
    max_tokens: 4000,
  })

  // DeepSeek 在 usage 附带 prompt_cache_hit_tokens / prompt_cache_miss_tokens，
  // 不在 openai 标准类型中，经 as any 读取（外部 API 字段的合理边界）
  const usage = res.usage as any
  const hit = usage?.prompt_cache_hit_tokens ?? usage?.prompt_tokens_details?.cached_tokens ?? 0
  const total = usage?.prompt_tokens ?? 0
  const miss = usage?.prompt_cache_miss_tokens ?? total - hit
  const pct = total ? Math.round((hit / total) * 100) : 0
  console.log(`\x1b[35m[KV] 输入 ${total} tokens：命中 ${hit} (${pct}%) / 未命中 ${miss}  [注入模式: ${injectMode}]\x1b[0m`)

  const msg = res.choices[0].message
  session.append("assistant/message", { message: msg }, true)
  if (!msg.tool_calls?.length) return false

  for (const call of msg.tool_calls) {
    const args = JSON.parse(call.function.arguments) as { command: string }
    console.log(`\x1b[33m$ ${args.command ?? JSON.stringify(args)}\x1b[0m`)
    const output: string = ctx.services.tools.execute(call.function.name, args)
    console.log(output.slice(0, 300))
    session.append("tool/result", { tool_call_id: call.id, content: output }, true)
    await ctx.emit("tools/result", { exec: { name: call.function.name, args }, result: { content: output } })
  }
  return true
}

async function runTurn(ctx: Ctx, session: Session, userText: string) {
  session.append("turn/start", { text: userText })
  session.append("user/message", { content: userText }, true)
  while (await step(ctx, session)) {}
  session.append("turn/end", {})
}

// ═══════════════════════════════════════════════════════════════
//  组装：新增 timeContextPlugin
// ═══════════════════════════════════════════════════════════════
const ctx = new Ctx()
ctx.provide("tools", createToolRegistry())
bashPlugin(ctx)
timeContextPlugin(ctx)
logPlugin(ctx)

const session = new Session()

const rl = readline.createInterface({ input: process.stdin, output: process.stdout })

console.log("L4 · 对 KV Cache 敏感")
console.log("每次回复后打印 [KV] 缓存命中。命令：")
console.log("  /append  上下文注入到末尾（append-only，正确）")
console.log("  /prepend 上下文注入到开头（对照，观察缓存失效）")
console.log("  /log /surface | q 退出")
console.log("对比：/append 连续提问观察命中率上升；切 /prepend 观察命中率下降。\n")

while (true) {
  const q = await rl.question("\x1b[36mL4 >> \x1b[0m")
  const cmd = q.trim().toLowerCase()
  if (["q", "exit", ""].includes(cmd)) break

  if (cmd === "/append" || cmd === "/prepend") {
    injectMode = cmd.slice(1) as "append" | "prepend"
    console.log(`\x1b[35m注入模式: ${injectMode}\x1b[0m\n`)
    continue
  }
  if (cmd === "/log") {
    console.log("\x1b[90m── 事件日志 ──\x1b[0m")
    for (const e of session.events) {
      const on = session.surface.includes(e.seq) ? "\x1b[32m[在 surface]\x1b[0m" : "\x1b[90m[仅日志]\x1b[0m"
      console.log(`  seq ${String(e.seq).padStart(2)} ${e.type.padEnd(18)} ${on}`)
    }
    console.log()
    continue
  }
  if (cmd === "/surface") {
    console.log(`\x1b[90msurface:\x1b[0m [${session.surface.join(", ")}]\n`)
    continue
  }

  await runTurn(ctx, session, q)
  const last = session.events[session.events.length - 2]
  if (last?.type === "assistant/message" && typeof last.data.message.content === "string") {
    console.log(last.data.message.content)
  }
  console.log()
}
rl.close()

/**
 * L5 · 工具管线 + 权限 (P1 + P2)
 *
 * 前几课工具执行是一次直接的函数调用。真实 harness 把它升级为一条分层管线，
 * 让权限、审计、结果改写各自作为独立环节接入：
 *
 *   pre-execute(瀑布: 允许/拒绝/询问) → guard(单调否决) → 执行 → post-execute(瀑布: 改写结果) → result(通知)
 *
 * 每一环都是一个扩展点，分别承载安全策略(权限)、不可绕过的硬规则(guard)、结果加工、观察。
 * 本课新增 read_file 作为第二个工具，并接入一个 permission 插件，对写/删类命令要求用户确认。
 *
 * 为聚焦管线，本课未叠加 L4 的上下文注入等插件；L8 会将各能力组装到一起。
 */

import OpenAI from "openai"
import type { ChatCompletionMessageParam, ChatCompletionTool } from "openai/resources/chat/completions"
import { execSync } from "node:child_process"
import { readFileSync } from "node:fs"
import * as readline from "node:readline/promises"
import "dotenv/config"

const client = new OpenAI({
  apiKey: process.env.DEEPSEEK_API_KEY,
  baseURL: process.env.DEEPSEEK_BASE_URL ?? "https://api.deepseek.com",
})
const MODEL = process.env.MODEL_ID ?? "deepseek-chat"
const SYSTEM = `You are a coding agent working in ${process.cwd()}. Use tools to accomplish tasks. Act, don't over-explain.`

// ═══════════════════════════════════════════════════════════════
//  迷你框架（同前）
// ═══════════════════════════════════════════════════════════════
type NextFn = () => Promise<any>
type Listener = (payload: any, next: NextFn) => Promise<any> | any

class Ctx {
  services: Record<string, any> = {}
  private listeners: Record<string, Listener[]> = {}
  provide(name: string, service: any) {
    this.services[name] = service
  }
  on(event: string, fn: Listener): () => void {
    ;(this.listeners[event] ??= []).push(fn)
    return () => {
      const arr = this.listeners[event]!
      arr.splice(arr.indexOf(fn), 1)
    }
  }
  async emit(event: string, payload: any): Promise<void> {
    for (const fn of this.listeners[event] ?? []) await fn(payload, async () => {})
  }
  async waterfall(event: string, payload: any, base: NextFn): Promise<any> {
    const chain = this.listeners[event] ?? []
    let i = 0
    const next: NextFn = () =>
      i < chain.length ? Promise.resolve(chain[i++](payload, next)) : base()
    return next()
  }
}

// ═══════════════════════════════════════════════════════════════
//  Session（同 L3）
// ═══════════════════════════════════════════════════════════════
type SurfaceType = "user/message" | "assistant/message" | "tool/result"
interface SessionEvent {
  seq: number
  type: SurfaceType | "turn/start" | "turn/end" | "tool/call"
  data: any
}

class Session {
  events: SessionEvent[] = []
  surface: number[] = []
  private seqCounter = 0
  append(type: SessionEvent["type"], data: any, onSurface = false): SessionEvent {
    const event: SessionEvent = { seq: this.seqCounter++, type, data }
    this.events.push(event)
    if (onSurface) this.surface.push(event.seq)
    return event
  }
  deriveMessages(): ChatCompletionMessageParam[] {
    // seq 等于事件在 events 中的下标（events 只增，seq 与 push 同步自增），故可直接索引
    return this.surface.map((seq) => {
      const e = this.events[seq]
      switch (e.type) {
        case "user/message":
          return { role: "user", content: e.data.content }
        case "assistant/message":
          return e.data.message
        case "tool/result":
          return { role: "tool", tool_call_id: e.data.tool_call_id, content: e.data.content }
        default:
          throw new Error(`非 surface 事件不应出现在 surface 列表中: ${e.type}`)
      }
    })
  }
}

// ═══════════════════════════════════════════════════════════════
//  ★ 本课主角：带分层管线的工具注册表
// ═══════════════════════════════════════════════════════════════
interface ToolExec {
  callId: string
  name: string
  args: any
}
interface ToolResult {
  content: string
  isError: boolean
}
// 允许 / 拒绝 / 询问用户
type PreToolDecision = { kind: "allow" } | { kind: "deny"; reason: string } | { kind: "ask"; reason: string }

function createToolRegistry(ctx: Ctx) {
  const tools: Record<string, { schema: any; run: (args: any) => string }> = {}
  const guards: Array<(exec: ToolExec) => string | undefined> = []

  return {
    register(name: string, schema: any, run: (args: any) => string) {
      tools[name] = { schema, run }
    },
    // 单调 guard：一旦某个 guard 拒绝，后续环节无法翻转（不可绕过的硬规则）
    guard(fn: (exec: ToolExec) => string | undefined) {
      guards.push(fn)
    },
    schemas(): ChatCompletionTool[] {
      return Object.entries(tools).map(([name, t]) => ({
        type: "function",
        function: { name, ...t.schema },
      }))
    },

    async execute(exec: ToolExec): Promise<ToolResult> {
      // 1) pre-execute 瀑布：插件给出 allow/deny/ask，默认 allow
      let decision: PreToolDecision = await ctx.waterfall(
        "tools/pre-execute",
        { exec },
        async () => ({ kind: "allow" }),
      )

      // 2) guard：单调否决，位于 pre-execute 之后，任何 ask 都无法翻转它
      for (const g of guards) {
        const reason = g(exec)
        if (reason) decision = { kind: "deny", reason }
      }

      // 3) ask：交由确认服务询问用户；无确认服务时降级为拒绝
      if (decision.kind === "ask") {
        const confirm = ctx.services.confirm as undefined | ((e: ToolExec, r: string) => Promise<boolean>)
        const ok = confirm ? await confirm(exec, decision.reason) : false
        decision = ok ? { kind: "allow" } : { kind: "deny", reason: "用户未批准" }
      }

      if (decision.kind === "deny") {
        return { content: `Error: 工具调用被拒绝 —— ${decision.reason}`, isError: true }
      }

      // 4) 执行
      const t = tools[exec.name]
      let result: ToolResult = t
        ? { content: t.run(exec.args), isError: false }
        : { content: `Error: 未知工具 ${exec.name}`, isError: true }

      // 5) post-execute 瀑布：插件可改写结果内容
      result = await ctx.waterfall("tools/post-execute", { exec, result }, async () => result)

      // 6) result 通知：仅供观察，不能改变结果
      await ctx.emit("tools/result", { exec, result })
      return result
    },
  }
}

// ═══════════════════════════════════════════════════════════════
//  工具插件
// ═══════════════════════════════════════════════════════════════
function bashPlugin(ctx: Ctx) {
  function runBash(command: string): string {
    try {
      const out = execSync(command, { encoding: "utf8", timeout: 120_000, stdio: ["ignore", "pipe", "pipe"] })
      return out.trim().slice(0, 50_000) || "(无输出)"
    } catch (e: any) {
      const out = ((e.stdout ?? "") + (e.stderr ?? "")).trim()
      return out ? out.slice(0, 50_000) : `Error: ${e.message}`
    }
  }
  ctx.services.tools.register(
    "bash",
    {
      description: "Run a shell command and return its output.",
      parameters: { type: "object", properties: { command: { type: "string" } }, required: ["command"] },
    },
    (args: { command: string }) => runBash(args.command),
  )
}

function readFilePlugin(ctx: Ctx) {
  ctx.services.tools.register(
    "read_file",
    {
      description: "Read a UTF-8 text file and return its content.",
      parameters: { type: "object", properties: { path: { type: "string" } }, required: ["path"] },
    },
    (args: { path: string }) => {
      try {
        return readFileSync(args.path, "utf8").slice(0, 50_000)
      } catch (e: any) {
        return `Error: ${e.message}`
      }
    },
  )
}

// ═══════════════════════════════════════════════════════════════
//  ★ 权限插件：策略与硬规则分离
//    · 硬规则用 guard：命中即拒绝，任何询问都无法翻转（如 rm -rf /）
//    · 一般写/删操作用 pre-execute 返回 ask，交由用户确认
// ═══════════════════════════════════════════════════════════════
function permissionPlugin(ctx: Ctx) {
  const registry = ctx.services.tools

  registry.guard((exec: ToolExec) => {
    if (exec.name === "bash" && /rm\s+-rf\s+\/(?!\w)|shutdown|reboot|:\(\)\s*\{/.test(exec.args.command ?? "")) {
      return "命中不可执行的危险模式"
    }
    return undefined
  })

  ctx.on("tools/pre-execute", ({ exec }: { exec: ToolExec }): PreToolDecision => {
    if (exec.name === "bash") {
      const cmd: string = exec.args.command ?? ""
      const mutating = /\b(rm|mv|cp|chmod|chown|git\s+push|>|>>|tee|mkdir|touch|npm\s+i)/.test(cmd)
      if (mutating) return { kind: "ask", reason: `即将执行可能修改系统的命令：${cmd}` }
    }
    return { kind: "allow" } // read_file 及只读命令直接放行
  })
}

// ═══════════════════════════════════════════════════════════════
//  循环：先记录 tool/call(审计意图)，再执行管线，最后记录 tool/result
// ═══════════════════════════════════════════════════════════════
async function step(ctx: Ctx, session: Session): Promise<boolean> {
  const messages: ChatCompletionMessageParam[] = await ctx.waterfall("agent/pre-step", { session }, async () => [
    { role: "system", content: SYSTEM },
    ...session.deriveMessages(),
  ])

  const res = await client.chat.completions.create({
    model: MODEL,
    messages,
    tools: ctx.services.tools.schemas(),
    max_tokens: 4000,
  })
  const msg = res.choices[0].message
  session.append("assistant/message", { message: msg }, true)
  if (!msg.tool_calls?.length) return false

  for (const call of msg.tool_calls) {
    const args = JSON.parse(call.function.arguments)
    const exec: ToolExec = { callId: call.id, name: call.function.name, args }
    // 先记录调用意图（log-only），再执行：崩溃时可判断某调用是否已发起
    session.append("tool/call", { callId: exec.callId, name: exec.name, args })
    console.log(`\x1b[33m$ ${exec.name} ${JSON.stringify(args)}\x1b[0m`)
    const result = await ctx.services.tools.execute(exec)
    console.log((result.isError ? "\x1b[31m" : "") + result.content.slice(0, 300) + "\x1b[0m")
    session.append("tool/result", { tool_call_id: call.id, content: result.content }, true)
  }
  return true
}

async function runTurn(ctx: Ctx, session: Session, userText: string) {
  session.append("turn/start", { text: userText })
  session.append("user/message", { content: userText }, true)
  while (await step(ctx, session)) {}
  session.append("turn/end", {})
}

// ═══════════════════════════════════════════════════════════════
//  组装
// ═══════════════════════════════════════════════════════════════
const ctx = new Ctx()
ctx.provide("tools", createToolRegistry(ctx))
bashPlugin(ctx)
readFilePlugin(ctx)
permissionPlugin(ctx)

const session = new Session()
const rl = readline.createInterface({ input: process.stdin, output: process.stdout })

// 确认服务：管线遇到 ask 时调用它询问用户。策略(问什么)在 permission 插件，机制(如何问)在这里
ctx.provide("confirm", async (_exec: ToolExec, reason: string): Promise<boolean> => {
  const a = await rl.question(`\x1b[31m[需要确认] ${reason}\n  允许执行? (y/N) \x1b[0m`)
  return a.trim().toLowerCase() === "y"
})

console.log("L5 · 工具管线 + 权限")
console.log("只读命令直接执行；写/删类命令会要求确认。输入 q 退出。\n")

while (true) {
  const q = await rl.question("\x1b[36mL5 >> \x1b[0m")
  if (["q", "exit", ""].includes(q.trim().toLowerCase())) break
  await runTurn(ctx, session, q)
  const last = session.events[session.events.length - 2]
  if (last?.type === "assistant/message" && typeof last.data.message.content === "string") {
    console.log(last.data.message.content)
  }
  console.log()
}
rl.close()

/**
 * L6 · 上下文压缩 (P1 + P2 + P3 三支柱合流)
 *
 * 对话变长后需要压缩：把较旧的一段替换为一条摘要，缩短后续请求。
 * 这一课让三根支柱同时发挥作用：
 *   P1 压缩是一个插件，挂在 agent/pre-step，循环不改
 *   P2 压缩不删日志——仅向日志追加 compact/* 与一条带 replace 的消息，改写 surface；原始事件保留
 *   P3 两处缓存要点：
 *      · 摘要请求复用当前对话前缀(把压缩指令放末尾)，避免为摘要重算整段
 *      · 压缩替换了 surface 中间一段，会使服务端缓存从该位置起失效——这是压缩的固有代价
 *
 * 为聚焦压缩，本课仅保留 bash 工具。
 */

import OpenAI from "openai"
import type { ChatCompletionMessageParam, ChatCompletionTool } from "openai/resources/chat/completions"
import { execSync } from "node:child_process"
import * as readline from "node:readline/promises"
import "dotenv/config"

const client = new OpenAI({
  apiKey: process.env.DEEPSEEK_API_KEY,
  baseURL: process.env.DEEPSEEK_BASE_URL ?? "https://api.deepseek.com",
})
const MODEL = process.env.MODEL_ID ?? "deepseek-chat"
const SYSTEM = `You are a coding agent working in ${process.cwd()}. Use tools to accomplish tasks. Act, don't over-explain.`

// ═══════════════════════════════════════════════════════════════
//  迷你框架（同前）
// ═══════════════════════════════════════════════════════════════
type NextFn = () => Promise<any>
type Listener = (payload: any, next: NextFn) => Promise<any> | any

class Ctx {
  services: Record<string, any> = {}
  private listeners: Record<string, Listener[]> = {}
  provide(name: string, service: any) {
    this.services[name] = service
  }
  on(event: string, fn: Listener): () => void {
    ;(this.listeners[event] ??= []).push(fn)
    return () => {
      const arr = this.listeners[event]!
      arr.splice(arr.indexOf(fn), 1)
    }
  }
  async emit(event: string, payload: any): Promise<void> {
    for (const fn of this.listeners[event] ?? []) await fn(payload, async () => {})
  }
  async waterfall(event: string, payload: any, base: NextFn): Promise<any> {
    const chain = this.listeners[event] ?? []
    let i = 0
    const next: NextFn = () =>
      i < chain.length ? Promise.resolve(chain[i++](payload, next)) : base()
    return next()
  }
}

// ═══════════════════════════════════════════════════════════════
//  Session：新增 replace 语义
// ═══════════════════════════════════════════════════════════════
type SurfaceType = "user/message" | "assistant/message" | "tool/result"
// append：进入 surface 末尾；replace：用本事件替换 surface 上 [start,end] 一段
type SurfaceOp = "append" | { op: "replace"; start: number; end: number }
interface SessionEvent {
  seq: number
  type: SurfaceType | "turn/start" | "turn/end" | "tool/call" | "compact/start" | "compact/summary" | "compact/end"
  data: any
}

class Session {
  events: SessionEvent[] = []
  surface: number[] = []
  private seqCounter = 0

  append(type: SessionEvent["type"], data: any, op?: SurfaceOp): SessionEvent {
    const event: SessionEvent = { seq: this.seqCounter++, type, data }
    this.events.push(event)
    if (op === "append") {
      this.surface.push(event.seq)
    } else if (op && op.op === "replace") {
      // 用新事件替换 surface 上 [start,end] 覆盖的连续区段；被替换的原事件仍留在日志中
      const i = this.surface.indexOf(op.start)
      const j = this.surface.indexOf(op.end)
      this.surface.splice(i, j - i + 1, event.seq)
    }
    return event
  }

  typeOfSeq(seq: number): string {
    return this.events.find((e) => e.seq === seq)!.type
  }

  deriveMessages(seqs: number[] = this.surface): ChatCompletionMessageParam[] {
    // seq 等于事件在 events 中的下标（events 只增，seq 与 push 同步自增），故可直接索引
    return seqs.map((seq) => {
      const e = this.events[seq]
      switch (e.type) {
        case "user/message":
          return { role: "user", content: e.data.content }
        case "assistant/message":
          return e.data.message
        case "tool/result":
          return { role: "tool", tool_call_id: e.data.tool_call_id, content: e.data.content }
        default:
          throw new Error(`非 surface 事件不应出现在 surface 列表中: ${e.type}`)
      }
    })
  }
}

// ═══════════════════════════════════════════════════════════════
//  工具注册表 + bash（简化版）
// ═══════════════════════════════════════════════════════════════
function createToolRegistry() {
  const tools: Record<string, { schema: any; run: (args: any) => string }> = {}
  return {
    register(name: string, schema: any, run: (args: any) => string) {
      tools[name] = { schema, run }
    },
    schemas(): ChatCompletionTool[] {
      return Object.entries(tools).map(([name, t]) => ({ type: "function", function: { name, ...t.schema } }))
    },
    execute(name: string, args: any): string {
      const t = tools[name]
      return t ? t.run(args) : `Error: 未知工具 ${name}`
    },
  }
}

function bashPlugin(ctx: Ctx) {
  ctx.services.tools.register(
    "bash",
    { description: "Run a shell command.", parameters: { type: "object", properties: { command: { type: "string" } }, required: ["command"] } },
    (args: { command: string }) => {
      try {
        return execSync(args.command, { encoding: "utf8", timeout: 120_000, stdio: ["ignore", "pipe", "pipe"] }).trim().slice(0, 50_000) || "(无输出)"
      } catch (e: any) {
        return (((e.stdout ?? "") + (e.stderr ?? "")).trim() || `Error: ${e.message}`).slice(0, 50_000)
      }
    },
  )
}

// ═══════════════════════════════════════════════════════════════
//  ★ 本课主角：压缩插件
// ═══════════════════════════════════════════════════════════════
const COMPACT_INSTRUCTION =
  "你现在是压缩引擎。请将上面的对话浓缩为一段简洁的检查点，保留目标、已完成的关键步骤、" +
  "重要结论与未决事项。只输出检查点正文，不要调用工具，不要提及本次压缩请求。"

// 摘要请求复用当前对话前缀：把 [system + 待压缩段] 作为前缀(它是刚发出的对话请求的前缀)，
// 压缩指令放在末尾。因此服务端可命中已有缓存，无需为摘要重算整段。
async function summarize(ctx: Ctx, rangeMsgs: ChatCompletionMessageParam[]): Promise<string> {
  const messages: ChatCompletionMessageParam[] = [
    { role: "system", content: SYSTEM },
    ...rangeMsgs,
    { role: "user", content: COMPACT_INSTRUCTION },
  ]
  const res = await client.chat.completions.create({
    model: MODEL,
    messages,
    tools: ctx.services.tools.schemas(), // 保持前缀与对话请求一致，最大化缓存复用
    max_tokens: 1024,
  })
  const hit = (res.usage as any)?.prompt_cache_hit_tokens ?? 0
  console.log(`\x1b[35m[compaction] 摘要请求复用对话前缀，缓存命中 ${hit} tokens\x1b[0m`)
  return res.choices[0].message.content ?? "(摘要为空)"
}

async function maybeCompact(ctx: Ctx, session: Session, threshold: number, retain: number, force = false) {
  if (!force && session.surface.length <= threshold) return
  if (session.surface.length <= retain) return

  let cut = session.surface.length - retain
  // 避免保留段以孤立的 tool/result 开头(其对应的 assistant 调用在被压缩段)：把这些 tool/result 并入压缩段
  while (cut < session.surface.length && session.typeOfSeq(session.surface[cut]) === "tool/result") cut++
  if (cut < 2) return

  const rangeSeqs = session.surface.slice(0, cut)
  const start = rangeSeqs[0]
  const end = rangeSeqs[rangeSeqs.length - 1]

  session.append("compact/start", { start, end }) // log-only：记录压缩区间
  const summary = await summarize(ctx, session.deriveMessages(rangeSeqs))
  session.append("compact/summary", { summary, shadowed: rangeSeqs }) // log-only：保留摘要与被遮蔽的 seq
  // 唯一的 surface 变更：用一条摘要消息替换被压缩区间；原事件仍在日志
  session.append("user/message", { content: `<compacted-summary>\n${summary}\n</compacted-summary>` }, { op: "replace", start, end })
  session.append("compact/end", {})

  console.log(`\x1b[35m[compaction] 已将 surface[${start}..${end}] 替换为一条摘要；该位置起的服务端缓存将失效(压缩的固有代价)\x1b[0m`)
}

// ═══════════════════════════════════════════════════════════════
//  循环
// ═══════════════════════════════════════════════════════════════
const THRESHOLD = 8 // surface 超过这么多条即自动压缩
const RETAIN = 4 // 保留最近这么多条不压缩

async function step(ctx: Ctx, session: Session): Promise<boolean> {
  // 压缩挂在 agent/pre-step 最前：先(可能)压缩，再由 base 从压缩后的 surface 派生消息
  const messages: ChatCompletionMessageParam[] = await ctx.waterfall("agent/pre-step", { session }, async () => [
    { role: "system", content: SYSTEM },
    ...session.deriveMessages(),
  ])

  const res = await client.chat.completions.create({ model: MODEL, messages, tools: ctx.services.tools.schemas(), max_tokens: 4000 })
  const msg = res.choices[0].message
  session.append("assistant/message", { message: msg }, "append")
  if (!msg.tool_calls?.length) return false

  for (const call of msg.tool_calls) {
    const args = JSON.parse(call.function.arguments)
    console.log(`\x1b[33m$ ${call.function.name} ${JSON.stringify(args)}\x1b[0m`)
    const output = ctx.services.tools.execute(call.function.name, args)
    console.log(output.slice(0, 200))
    session.append("tool/result", { tool_call_id: call.id, content: output }, "append")
  }
  return true
}

function compactionPlugin(ctx: Ctx) {
  ctx.on("agent/pre-step", async ({ session }: { session: Session }, next: NextFn) => {
    await maybeCompact(ctx, session, THRESHOLD, RETAIN)
    return next()
  })
}

async function runTurn(ctx: Ctx, session: Session, userText: string) {
  session.append("turn/start", { text: userText })
  session.append("user/message", { content: userText }, "append")
  while (await step(ctx, session)) {}
  session.append("turn/end", {})
}

// ═══════════════════════════════════════════════════════════════
//  组装
// ═══════════════════════════════════════════════════════════════
const ctx = new Ctx()
ctx.provide("tools", createToolRegistry())
bashPlugin(ctx)
compactionPlugin(ctx)

const session = new Session()
const rl = readline.createInterface({ input: process.stdin, output: process.stdout })

console.log("L6 · 上下文压缩")
console.log(`surface 超过 ${THRESHOLD} 条自动压缩，保留最近 ${RETAIN} 条。命令：`)
console.log("  /compact 立即压缩 | /log 查看日志与 surface | q 退出\n")

while (true) {
  const q = await rl.question("\x1b[36mL6 >> \x1b[0m")
  const cmd = q.trim().toLowerCase()
  if (["q", "exit", ""].includes(cmd)) break

  if (cmd === "/compact") {
    await maybeCompact(ctx, session, THRESHOLD, RETAIN, true)
    console.log()
    continue
  }
  if (cmd === "/log") {
    console.log("\x1b[90m── 事件日志（含被压缩遮蔽的原始事件，均保留）──\x1b[0m")
    for (const e of session.events) {
      const on = session.surface.includes(e.seq) ? "\x1b[32m[在 surface]\x1b[0m" : "\x1b[90m[仅日志]\x1b[0m"
      console.log(`  seq ${String(e.seq).padStart(2)} ${e.type.padEnd(16)} ${on}`)
    }
    console.log(`\x1b[90msurface:\x1b[0m [${session.surface.join(", ")}]\n`)
    continue
  }

  await runTurn(ctx, session, q)
  const last = session.events[session.events.length - 2]
  if (last?.type === "assistant/message" && typeof last.data.message.content === "string") {
    console.log(last.data.message.content)
  }
  console.log()
}
rl.close()

/**
 * L7 · 跨 session 记忆 (P2 + P3)
 *
 * 前几课的对话都随进程结束而消失。这一课让 agent 具备跨会话记忆：
 *   写入：模型可调用 remember 工具，把关于用户/项目的事实存入磁盘文件
 *   召回：新会话开始时，读回这些事实并注入对话
 *
 * 支柱关联：
 *   P2 记忆写入是一次持久化追加（与事件日志同理：只增）；召回把事实作为一条事件进入 surface
 *   P3 召回的事实作为较早且稳定的一条注入一次，保持前缀稳定、缓存友好；
 *      若改为每轮按相关性重排注入不同内容，则会改变较早的前缀、破坏缓存——这正是需要
 *      位置无关缓存(PIC)的场景
 *
 * 为聚焦记忆，本课保留 bash 工具，未叠加压缩等插件。
 */

import OpenAI from "openai"
import type { ChatCompletionMessageParam, ChatCompletionTool } from "openai/resources/chat/completions"
import { execSync } from "node:child_process"
import { existsSync, readFileSync, writeFileSync } from "node:fs"
import * as readline from "node:readline/promises"
import "dotenv/config"

const client = new OpenAI({
  apiKey: process.env.DEEPSEEK_API_KEY,
  baseURL: process.env.DEEPSEEK_BASE_URL ?? "https://api.deepseek.com",
})
const MODEL = process.env.MODEL_ID ?? "deepseek-chat"
const SYSTEM = `You are a coding agent working in ${process.cwd()}. Use tools to accomplish tasks. When the user tells you a durable fact about themselves or the project, call remember to save it. Act, don't over-explain.`

// ═══════════════════════════════════════════════════════════════
//  迷你框架（同前）
// ═══════════════════════════════════════════════════════════════
type NextFn = () => Promise<any>
type Listener = (payload: any, next: NextFn) => Promise<any> | any

class Ctx {
  services: Record<string, any> = {}
  private listeners: Record<string, Listener[]> = {}
  provide(name: string, service: any) {
    this.services[name] = service
  }
  on(event: string, fn: Listener): () => void {
    ;(this.listeners[event] ??= []).push(fn)
    return () => {
      const arr = this.listeners[event]!
      arr.splice(arr.indexOf(fn), 1)
    }
  }
  async emit(event: string, payload: any): Promise<void> {
    for (const fn of this.listeners[event] ?? []) await fn(payload, async () => {})
  }
  async waterfall(event: string, payload: any, base: NextFn): Promise<any> {
    const chain = this.listeners[event] ?? []
    let i = 0
    const next: NextFn = () =>
      i < chain.length ? Promise.resolve(chain[i++](payload, next)) : base()
    return next()
  }
}

// ═══════════════════════════════════════════════════════════════
//  Session（同 L3）
// ═══════════════════════════════════════════════════════════════
type SurfaceType = "user/message" | "assistant/message" | "tool/result"
interface SessionEvent {
  seq: number
  type: SurfaceType | "turn/start" | "turn/end"
  data: any
}

class Session {
  events: SessionEvent[] = []
  surface: number[] = []
  private seqCounter = 0
  append(type: SessionEvent["type"], data: any, onSurface = false): SessionEvent {
    const event: SessionEvent = { seq: this.seqCounter++, type, data }
    this.events.push(event)
    if (onSurface) this.surface.push(event.seq)
    return event
  }
  deriveMessages(): ChatCompletionMessageParam[] {
    // seq 等于事件在 events 中的下标（events 只增，seq 与 push 同步自增），故可直接索引
    return this.surface.map((seq) => {
      const e = this.events[seq]
      switch (e.type) {
        case "user/message":
          return { role: "user", content: e.data.content }
        case "assistant/message":
          return e.data.message
        case "tool/result":
          return { role: "tool", tool_call_id: e.data.tool_call_id, content: e.data.content }
        default:
          throw new Error(`非 surface 事件不应出现在 surface 列表中: ${e.type}`)
      }
    })
  }
}

// ═══════════════════════════════════════════════════════════════
//  工具注册表 + bash
// ═══════════════════════════════════════════════════════════════
function createToolRegistry() {
  const tools: Record<string, { schema: any; run: (args: any) => string }> = {}
  return {
    register(name: string, schema: any, run: (args: any) => string) {
      tools[name] = { schema, run }
    },
    schemas(): ChatCompletionTool[] {
      return Object.entries(tools).map(([name, t]) => ({ type: "function", function: { name, ...t.schema } }))
    },
    execute(name: string, args: any): string {
      const t = tools[name]
      return t ? t.run(args) : `Error: 未知工具 ${name}`
    },
  }
}

function bashPlugin(ctx: Ctx) {
  ctx.services.tools.register(
    "bash",
    { description: "Run a shell command.", parameters: { type: "object", properties: { command: { type: "string" } }, required: ["command"] } },
    (args: { command: string }) => {
      try {
        return execSync(args.command, { encoding: "utf8", timeout: 120_000, stdio: ["ignore", "pipe", "pipe"] }).trim().slice(0, 50_000) || "(无输出)"
      } catch (e: any) {
        return (((e.stdout ?? "") + (e.stderr ?? "")).trim() || `Error: ${e.message}`).slice(0, 50_000)
      }
    },
  )
}

// ═══════════════════════════════════════════════════════════════
//  ★ 本课主角：记忆插件
// ═══════════════════════════════════════════════════════════════
const MEMORY_FILE = "agent-memory.json"

function memoryPlugin(ctx: Ctx) {
  type Memory = { text: string; ts: string }
  const memories: Memory[] = existsSync(MEMORY_FILE) ? JSON.parse(readFileSync(MEMORY_FILE, "utf8")) : []
  let recalled = false

  // 写入：remember 工具。持久化到磁盘文件，供未来会话读取
  ctx.services.tools.register(
    "remember",
    {
      description: "Save a durable fact about the user or project for future sessions.",
      parameters: { type: "object", properties: { fact: { type: "string" } }, required: ["fact"] },
    },
    (args: { fact: string }) => {
      memories.push({ text: args.fact, ts: new Date().toISOString() })
      writeFileSync(MEMORY_FILE, JSON.stringify(memories, null, 2))
      return `已记住：${args.fact}`
    },
  )

  // 召回：本会话首次 agent/pre-step 时，把既有事实作为一条事件写入 surface（仅一次）。
  // 它较早且稳定，故对缓存友好。真实系统会按相关性检索，这里注入全部。
  ctx.on("agent/pre-step", async ({ session }: { session: Session }, next: NextFn) => {
    if (!recalled && memories.length) {
      recalled = true
      const list = memories.map((m, i) => `${i + 1}. ${m.text}`).join("\n")
      session.append("user/message", { content: `[记忆] 关于用户/项目的既有事实：\n${list}` }, true)
      console.log(`\x1b[35m[memory] 已召回 ${memories.length} 条记忆\x1b[0m`)
    }
    return next()
  })
}

// ═══════════════════════════════════════════════════════════════
//  循环（同 L3）
// ═══════════════════════════════════════════════════════════════
async function step(ctx: Ctx, session: Session): Promise<boolean> {
  const messages: ChatCompletionMessageParam[] = await ctx.waterfall("agent/pre-step", { session }, async () => [
    { role: "system", content: SYSTEM },
    ...session.deriveMessages(),
  ])
  const res = await client.chat.completions.create({ model: MODEL, messages, tools: ctx.services.tools.schemas(), max_tokens: 4000 })
  const msg = res.choices[0].message
  session.append("assistant/message", { message: msg }, true)
  if (!msg.tool_calls?.length) return false
  for (const call of msg.tool_calls) {
    const args = JSON.parse(call.function.arguments)
    console.log(`\x1b[33m$ ${call.function.name} ${JSON.stringify(args)}\x1b[0m`)
    const output = ctx.services.tools.execute(call.function.name, args)
    console.log(output.slice(0, 200))
    session.append("tool/result", { tool_call_id: call.id, content: output }, true)
  }
  return true
}

async function runTurn(ctx: Ctx, session: Session, userText: string) {
  session.append("turn/start", { text: userText })
  session.append("user/message", { content: userText }, true)
  while (await step(ctx, session)) {}
  session.append("turn/end", {})
}

// ═══════════════════════════════════════════════════════════════
//  组装
// ═══════════════════════════════════════════════════════════════
const ctx = new Ctx()
ctx.provide("tools", createToolRegistry())
bashPlugin(ctx)
memoryPlugin(ctx)

const session = new Session()
const rl = readline.createInterface({ input: process.stdin, output: process.stdout })

console.log("L7 · 跨 session 记忆")
console.log(`记忆存于 ${MEMORY_FILE}。告诉它关于你的事实，退出后重跑即可召回。输入 q 退出。\n`)

while (true) {
  const q = await rl.question("\x1b[36mL7 >> \x1b[0m")
  if (["q", "exit", ""].includes(q.trim().toLowerCase())) break
  await runTurn(ctx, session, q)
  const last = session.events[session.events.length - 2]
  if (last?.type === "assistant/message" && typeof last.data.message.content === "string") {
    console.log(last.data.message.content)
  }
  console.log()
}
rl.close()

/**
 * L8 · 组装成小 harness (三支柱合力)
 *
 * 前面各课分别做出了插件：工具管线与权限(L5)、压缩(L6)、记忆(L7)、上下文注入(L4)。
 * 这一课把它们组装到一起，得到一个完整可用的小 harness。
 *
 * 全课的收束点在文件末尾的「组装」段——新增任意能力只需加一行，循环与其它插件都不动。
 * 这就是「一切皆插件」的复利：能力正交、可自由增删。
 */

import OpenAI from "openai"
import type { ChatCompletionMessageParam, ChatCompletionTool } from "openai/resources/chat/completions"
import { execSync } from "node:child_process"
import { existsSync, readFileSync, writeFileSync } from "node:fs"
import * as readline from "node:readline/promises"
import "dotenv/config"

const client = new OpenAI({
  apiKey: process.env.DEEPSEEK_API_KEY,
  baseURL: process.env.DEEPSEEK_BASE_URL ?? "https://api.deepseek.com",
})
const MODEL = process.env.MODEL_ID ?? "deepseek-chat"
const SYSTEM = `You are a coding agent working in ${process.cwd()}. Use tools to accomplish tasks. When the user states a durable fact about themselves or the project, call remember. Act, don't over-explain.`

// ═══════════════════════════════════════════════════════════════
//  迷你框架
// ═══════════════════════════════════════════════════════════════
type NextFn = () => Promise<any>
type Listener = (payload: any, next: NextFn) => Promise<any> | any

class Ctx {
  services: Record<string, any> = {}
  private listeners: Record<string, Listener[]> = {}
  provide(name: string, service: any) {
    this.services[name] = service
  }
  on(event: string, fn: Listener): () => void {
    ;(this.listeners[event] ??= []).push(fn)
    return () => {
      const arr = this.listeners[event]!
      arr.splice(arr.indexOf(fn), 1)
    }
  }
  async emit(event: string, payload: any): Promise<void> {
    for (const fn of this.listeners[event] ?? []) await fn(payload, async () => {})
  }
  async waterfall(event: string, payload: any, base: NextFn): Promise<any> {
    const chain = this.listeners[event] ?? []
    let i = 0
    const next: NextFn = () =>
      i < chain.length ? Promise.resolve(chain[i++](payload, next)) : base()
    return next()
  }
}

// ═══════════════════════════════════════════════════════════════
//  Session（含 replace，来自 L6）
// ═══════════════════════════════════════════════════════════════
type SurfaceType = "user/message" | "assistant/message" | "tool/result"
type SurfaceOp = "append" | { op: "replace"; start: number; end: number }
interface SessionEvent {
  seq: number
  type: SurfaceType | "turn/start" | "turn/end" | "tool/call" | "compact/start" | "compact/summary" | "compact/end"
  data: any
}

class Session {
  events: SessionEvent[] = []
  surface: number[] = []
  private seqCounter = 0
  append(type: SessionEvent["type"], data: any, op?: SurfaceOp): SessionEvent {
    const event: SessionEvent = { seq: this.seqCounter++, type, data }
    this.events.push(event)
    if (op === "append") this.surface.push(event.seq)
    else if (op && op.op === "replace") {
      const i = this.surface.indexOf(op.start)
      const j = this.surface.indexOf(op.end)
      this.surface.splice(i, j - i + 1, event.seq)
    }
    return event
  }
  typeOfSeq(seq: number): string {
    return this.events.find((e) => e.seq === seq)!.type
  }
  deriveMessages(seqs: number[] = this.surface): ChatCompletionMessageParam[] {
    // seq 等于事件在 events 中的下标（events 只增，seq 与 push 同步自增），故可直接索引
    return seqs.map((seq) => {
      const e = this.events[seq]
      switch (e.type) {
        case "user/message":
          return { role: "user", content: e.data.content }
        case "assistant/message":
          return e.data.message
        case "tool/result":
          return { role: "tool", tool_call_id: e.data.tool_call_id, content: e.data.content }
        default:
          throw new Error(`非 surface 事件不应出现在 surface 列表中: ${e.type}`)
      }
    })
  }
}

// ═══════════════════════════════════════════════════════════════
//  带管线的工具注册表（来自 L5）
// ═══════════════════════════════════════════════════════════════
interface ToolExec {
  callId: string
  name: string
  args: any
}
interface ToolResult {
  content: string
  isError: boolean
}
type PreToolDecision = { kind: "allow" } | { kind: "deny"; reason: string } | { kind: "ask"; reason: string }

function createToolRegistry(ctx: Ctx) {
  const tools: Record<string, { schema: any; run: (args: any) => string }> = {}
  const guards: Array<(exec: ToolExec) => string | undefined> = []
  return {
    register(name: string, schema: any, run: (args: any) => string) {
      tools[name] = { schema, run }
    },
    guard(fn: (exec: ToolExec) => string | undefined) {
      guards.push(fn)
    },
    schemas(): ChatCompletionTool[] {
      return Object.entries(tools).map(([name, t]) => ({ type: "function", function: { name, ...t.schema } }))
    },
    async execute(exec: ToolExec): Promise<ToolResult> {
      let decision: PreToolDecision = await ctx.waterfall("tools/pre-execute", { exec }, async () => ({ kind: "allow" }))
      for (const g of guards) {
        const r = g(exec)
        if (r) decision = { kind: "deny", reason: r }
      }
      if (decision.kind === "ask") {
        const confirm = ctx.services.confirm as undefined | ((e: ToolExec, r: string) => Promise<boolean>)
        decision = confirm && (await confirm(exec, decision.reason)) ? { kind: "allow" } : { kind: "deny", reason: "用户未批准" }
      }
      if (decision.kind === "deny") return { content: `Error: 工具调用被拒绝 —— ${decision.reason}`, isError: true }
      const t = tools[exec.name]
      let result: ToolResult = t ? { content: t.run(exec.args), isError: false } : { content: `Error: 未知工具 ${exec.name}`, isError: true }
      result = await ctx.waterfall("tools/post-execute", { exec, result }, async () => result)
      await ctx.emit("tools/result", { exec, result })
      return result
    },
  }
}

// ═══════════════════════════════════════════════════════════════
//  插件们（各自独立，均来自前面的课）
// ═══════════════════════════════════════════════════════════════
function bashPlugin(ctx: Ctx) {
  ctx.services.tools.register(
    "bash",
    { description: "Run a shell command.", parameters: { type: "object", properties: { command: { type: "string" } }, required: ["command"] } },
    (args: { command: string }) => {
      try {
        return execSync(args.command, { encoding: "utf8", timeout: 120_000, stdio: ["ignore", "pipe", "pipe"] }).trim().slice(0, 50_000) || "(无输出)"
      } catch (e: any) {
        return (((e.stdout ?? "") + (e.stderr ?? "")).trim() || `Error: ${e.message}`).slice(0, 50_000)
      }
    },
  )
}

function readFilePlugin(ctx: Ctx) {
  ctx.services.tools.register(
    "read_file",
    { description: "Read a UTF-8 text file.", parameters: { type: "object", properties: { path: { type: "string" } }, required: ["path"] } },
    (args: { path: string }) => {
      try {
        return readFileSync(args.path, "utf8").slice(0, 50_000)
      } catch (e: any) {
        return `Error: ${e.message}`
      }
    },
  )
}

function permissionPlugin(ctx: Ctx) {
  ctx.services.tools.guard((exec: ToolExec) =>
    exec.name === "bash" && /rm\s+-rf\s+\/(?!\w)|shutdown|reboot/.test(exec.args.command ?? "") ? "命中不可执行的危险模式" : undefined,
  )
  ctx.on("tools/pre-execute", ({ exec }: { exec: ToolExec }): PreToolDecision => {
    if (exec.name === "bash" && /\b(rm|mv|cp|chmod|git\s+push|>|>>|tee|mkdir|touch|npm\s+i)/.test(exec.args.command ?? "")) {
      return { kind: "ask", reason: `即将执行可能修改系统的命令：${exec.args.command}` }
    }
    return { kind: "allow" }
  })
}

function timeContextPlugin(ctx: Ctx) {
  // 追加到末尾，保持前缀稳定（P3）
  ctx.on("agent/pre-step", async (_p: unknown, next: NextFn) => {
    const messages: ChatCompletionMessageParam[] = await next()
    return [...messages, { role: "user", content: `[上下文] 当前时间：${new Date().toISOString()}` }]
  })
}

const MEMORY_FILE = "agent-memory.json"
function memoryPlugin(ctx: Ctx) {
  type Memory = { text: string; ts: string }
  const memories: Memory[] = existsSync(MEMORY_FILE) ? JSON.parse(readFileSync(MEMORY_FILE, "utf8")) : []
  let recalled = false
  ctx.services.tools.register(
    "remember",
    { description: "Save a durable fact for future sessions.", parameters: { type: "object", properties: { fact: { type: "string" } }, required: ["fact"] } },
    (args: { fact: string }) => {
      memories.push({ text: args.fact, ts: new Date().toISOString() })
      writeFileSync(MEMORY_FILE, JSON.stringify(memories, null, 2))
      return `已记住：${args.fact}`
    },
  )
  ctx.on("agent/pre-step", async ({ session }: { session: Session }, next: NextFn) => {
    if (!recalled && memories.length) {
      recalled = true
      session.append("user/message", { content: `[记忆] 既有事实：\n${memories.map((m, i) => `${i + 1}. ${m.text}`).join("\n")}` }, "append")
    }
    return next()
  })
}

const COMPACT_INSTRUCTION = "你现在是压缩引擎。请将上面的对话浓缩为一段简洁检查点，保留目标、关键步骤、结论与未决事项。只输出正文，不要调用工具，不要提及本次压缩。"
function compactionPlugin(ctx: Ctx, threshold = 10, retain = 4) {
  async function summarize(rangeMsgs: ChatCompletionMessageParam[]): Promise<string> {
    // 复用对话前缀 + 指令后置，最大化缓存命中（P3）
    const messages: ChatCompletionMessageParam[] = [{ role: "system", content: SYSTEM }, ...rangeMsgs, { role: "user", content: COMPACT_INSTRUCTION }]
    const res = await client.chat.completions.create({ model: MODEL, messages, tools: ctx.services.tools.schemas(), max_tokens: 1024 })
    return res.choices[0].message.content ?? "(摘要为空)"
  }
  ctx.on("agent/pre-step", async ({ session }: { session: Session }, next: NextFn) => {
    if (session.surface.length > threshold && session.surface.length > retain) {
      let cut = session.surface.length - retain
      while (cut < session.surface.length && session.typeOfSeq(session.surface[cut]) === "tool/result") cut++
      if (cut >= 2) {
        const range = session.surface.slice(0, cut)
        const start = range[0]
        const end = range[range.length - 1]
        session.append("compact/start", { start, end })
        const summary = await summarize(session.deriveMessages(range))
        session.append("compact/summary", { summary, shadowed: range })
        session.append("user/message", { content: `<compacted-summary>\n${summary}\n</compacted-summary>` }, { op: "replace", start, end })
        session.append("compact/end", {})
        console.log(`\x1b[35m[compaction] 已压缩 surface[${start}..${end}]\x1b[0m`)
      }
    }
    return next()
  })
}

// ═══════════════════════════════════════════════════════════════
//  循环
// ═══════════════════════════════════════════════════════════════
async function step(ctx: Ctx, session: Session): Promise<boolean> {
  const messages: ChatCompletionMessageParam[] = await ctx.waterfall("agent/pre-step", { session }, async () => [
    { role: "system", content: SYSTEM },
    ...session.deriveMessages(),
  ])
  const res = await client.chat.completions.create({ model: MODEL, messages, tools: ctx.services.tools.schemas(), max_tokens: 4000 })
  const msg = res.choices[0].message
  session.append("assistant/message", { message: msg }, "append")
  if (!msg.tool_calls?.length) return false
  for (const call of msg.tool_calls) {
    const args = JSON.parse(call.function.arguments)
    const exec: ToolExec = { callId: call.id, name: call.function.name, args }
    session.append("tool/call", { callId: exec.callId, name: exec.name, args })
    console.log(`\x1b[33m$ ${exec.name} ${JSON.stringify(args)}\x1b[0m`)
    const result = await ctx.services.tools.execute(exec)
    console.log((result.isError ? "\x1b[31m" : "") + result.content.slice(0, 200) + "\x1b[0m")
    session.append("tool/result", { tool_call_id: call.id, content: result.content }, "append")
  }
  return true
}

async function runTurn(ctx: Ctx, session: Session, userText: string) {
  session.append("turn/start", { text: userText })
  session.append("user/message", { content: userText }, "append")
  while (await step(ctx, session)) {}
  session.append("turn/end", {})
}

// ═══════════════════════════════════════════════════════════════
//  组装：一个完整 harness。增删能力只改这一段
// ═══════════════════════════════════════════════════════════════
const ctx = new Ctx()
ctx.provide("tools", createToolRegistry(ctx))
bashPlugin(ctx)
readFilePlugin(ctx)
permissionPlugin(ctx)
memoryPlugin(ctx)
timeContextPlugin(ctx)
compactionPlugin(ctx)

const session = new Session()
const rl = readline.createInterface({ input: process.stdin, output: process.stdout })
ctx.provide("confirm", async (_e: ToolExec, reason: string) => (await rl.question(`\x1b[31m[确认] ${reason}\n  允许? (y/N) \x1b[0m`)).trim().toLowerCase() === "y")

console.log("L8 · 组装成小 harness")
console.log("已装载：bash + read_file + 权限 + 记忆 + 时间上下文 + 压缩。输入 q 退出。\n")

while (true) {
  const q = await rl.question("\x1b[36mL8 >> \x1b[0m")
  if (["q", "exit", ""].includes(q.trim().toLowerCase())) break
  await runTurn(ctx, session, q)
  const last = session.events[session.events.length - 2]
  if (last?.type === "assistant/message" && typeof last.data.message.content === "string") console.log(last.data.message.content)
  console.log()
}
rl.close()

/**
 * L9 · 子 agent (P1)
 *
 * 把「派生一个带独立上下文的子循环」做成一个工具：spawn_subagent(task)。
 * 子 agent 有自己独立的 Session，完成任务后只把最终结果回传给父 agent。
 *
 * 关键价值是上下文隔离：子 agent 探索过程中的大量工具调用与中间输出留在它自己的
 * Session 里，不进入父 agent 的上下文。父 agent 只收到一段结论，上下文因而保持精简
 * （也利于缓存与成本，呼应 P3）。子 agent 本身就是同一套循环——「一切皆插件」下，
 * 它只是又一个被工具触发的循环实例。
 */

import OpenAI from "openai"
import type { ChatCompletionMessageParam, ChatCompletionTool } from "openai/resources/chat/completions"
import { execSync } from "node:child_process"
import * as readline from "node:readline/promises"
import "dotenv/config"

const client = new OpenAI({
  apiKey: process.env.DEEPSEEK_API_KEY,
  baseURL: process.env.DEEPSEEK_BASE_URL ?? "https://api.deepseek.com",
})
const MODEL = process.env.MODEL_ID ?? "deepseek-chat"
const SYSTEM = `You are a coding agent working in ${process.cwd()}. For a self-contained sub-task that would involve many exploratory steps, delegate it via spawn_subagent to keep your own context clean. Act, don't over-explain.`
const CHILD_SYSTEM = `You are a sub-agent with an isolated context. Complete the delegated task using bash, then report a concise final result. You cannot delegate further.`

// ═══════════════════════════════════════════════════════════════
//  迷你框架（同前）
// ═══════════════════════════════════════════════════════════════
type NextFn = () => Promise<any>
type Listener = (payload: any, next: NextFn) => Promise<any> | any

class Ctx {
  services: Record<string, any> = {}
  private listeners: Record<string, Listener[]> = {}
  provide(name: string, service: any) {
    this.services[name] = service
  }
  on(event: string, fn: Listener): () => void {
    ;(this.listeners[event] ??= []).push(fn)
    return () => {
      const arr = this.listeners[event]!
      arr.splice(arr.indexOf(fn), 1)
    }
  }
  async emit(event: string, payload: any): Promise<void> {
    for (const fn of this.listeners[event] ?? []) await fn(payload, async () => {})
  }
  async waterfall(event: string, payload: any, base: NextFn): Promise<any> {
    const chain = this.listeners[event] ?? []
    let i = 0
    const next: NextFn = () =>
      i < chain.length ? Promise.resolve(chain[i++](payload, next)) : base()
    return next()
  }
}

// ═══════════════════════════════════════════════════════════════
//  Session（同 L3）
// ═══════════════════════════════════════════════════════════════
type SurfaceType = "user/message" | "assistant/message" | "tool/result"
interface SessionEvent {
  seq: number
  type: SurfaceType | "turn/start" | "turn/end"
  data: any
}

class Session {
  events: SessionEvent[] = []
  surface: number[] = []
  private seqCounter = 0
  append(type: SessionEvent["type"], data: any, onSurface = false): SessionEvent {
    const event: SessionEvent = { seq: this.seqCounter++, type, data }
    this.events.push(event)
    if (onSurface) this.surface.push(event.seq)
    return event
  }
  deriveMessages(): ChatCompletionMessageParam[] {
    // seq 等于事件在 events 中的下标（events 只增，seq 与 push 同步自增），故可直接索引
    return this.surface.map((seq) => {
      const e = this.events[seq]
      switch (e.type) {
        case "user/message":
          return { role: "user", content: e.data.content }
        case "assistant/message":
          return e.data.message
        case "tool/result":
          return { role: "tool", tool_call_id: e.data.tool_call_id, content: e.data.content }
        default:
          throw new Error(`非 surface 事件不应出现在 surface 列表中: ${e.type}`)
      }
    })
  }
}

// ═══════════════════════════════════════════════════════════════
//  工具注册表：execute 改为异步（子 agent 的执行是异步的）
// ═══════════════════════════════════════════════════════════════
function createToolRegistry() {
  const tools: Record<string, { schema: any; run: (args: any) => string | Promise<string> }> = {}
  return {
    register(name: string, schema: any, run: (args: any) => string | Promise<string>) {
      tools[name] = { schema, run }
    },
    schemas(): ChatCompletionTool[] {
      return Object.entries(tools).map(([name, t]) => ({ type: "function", function: { name, ...t.schema } }))
    },
    // 仅暴露指定名字的工具 schema，用于给子 agent 一个受限工具集（防止无限委派）
    schemasFor(names: string[]): ChatCompletionTool[] {
      return this.schemas().filter((t) => names.includes(t.function.name))
    },
    async execute(name: string, args: any): Promise<string> {
      const t = tools[name]
      return t ? await t.run(args) : `Error: 未知工具 ${name}`
    },
  }
}

function bashPlugin(ctx: Ctx) {
  ctx.services.tools.register(
    "bash",
    { description: "Run a shell command.", parameters: { type: "object", properties: { command: { type: "string" } }, required: ["command"] } },
    (args: { command: string }) => {
      try {
        return execSync(args.command, { encoding: "utf8", timeout: 120_000, stdio: ["ignore", "pipe", "pipe"] }).trim().slice(0, 50_000) || "(无输出)"
      } catch (e: any) {
        return (((e.stdout ?? "") + (e.stderr ?? "")).trim() || `Error: ${e.message}`).slice(0, 50_000)
      }
    },
  )
}

// ═══════════════════════════════════════════════════════════════
//  ★ 本课主角：子 agent
// ═══════════════════════════════════════════════════════════════

// 运行一个拥有独立 Session、受限工具集(仅 bash)的子循环，直至其不再调用工具，返回最终文本
async function runSubagent(ctx: Ctx, task: string): Promise<string> {
  const child = new Session()
  child.append("user/message", { content: task }, true)
  const childTools = ctx.services.tools.schemasFor(["bash"]) // 不含 spawn_subagent，避免无限委派

  for (let guard = 0; guard < 20; guard++) {
    const messages: ChatCompletionMessageParam[] = [{ role: "system", content: CHILD_SYSTEM }, ...child.deriveMessages()]
    const res = await client.chat.completions.create({ model: MODEL, messages, tools: childTools, max_tokens: 2000 })
    const msg = res.choices[0].message
    child.append("assistant/message", { message: msg }, true)
    if (!msg.tool_calls?.length) return typeof msg.content === "string" ? msg.content : "(子 agent 无输出)"
    for (const call of msg.tool_calls) {
      const args = JSON.parse(call.function.arguments)
      console.log(`\x1b[90m    [子 agent] $ ${args.command}\x1b[0m`)
      const output = await ctx.services.tools.execute(call.function.name, args)
      child.append("tool/result", { tool_call_id: call.id, content: output }, true)
    }
  }
  return "(子 agent 超出步数上限)"
}

function subagentPlugin(ctx: Ctx) {
  ctx.services.tools.register(
    "spawn_subagent",
    {
      description: "Delegate a self-contained sub-task to a fresh sub-agent with its own isolated context. Returns only its final result.",
      parameters: { type: "object", properties: { task: { type: "string", description: "the self-contained task description" } }, required: ["task"] },
    },
    async (args: { task: string }) => {
      console.log(`\x1b[90m  [派生子 agent] ${args.task}\x1b[0m`)
      return await runSubagent(ctx, args.task) // 只有这段返回值进入父 agent 的上下文
    },
  )
}

// ═══════════════════════════════════════════════════════════════
//  父循环（execute 现为异步）
// ═══════════════════════════════════════════════════════════════
async function step(ctx: Ctx, session: Session): Promise<boolean> {
  const messages: ChatCompletionMessageParam[] = await ctx.waterfall("agent/pre-step", { session }, async () => [
    { role: "system", content: SYSTEM },
    ...session.deriveMessages(),
  ])
  const res = await client.chat.completions.create({ model: MODEL, messages, tools: ctx.services.tools.schemas(), max_tokens: 4000 })
  const msg = res.choices[0].message
  session.append("assistant/message", { message: msg }, true)
  if (!msg.tool_calls?.length) return false
  for (const call of msg.tool_calls) {
    const args = JSON.parse(call.function.arguments)
    console.log(`\x1b[33m$ ${call.function.name} ${JSON.stringify(args)}\x1b[0m`)
    const output = await ctx.services.tools.execute(call.function.name, args)
    console.log(output.slice(0, 200))
    session.append("tool/result", { tool_call_id: call.id, content: output }, true)
  }
  return true
}

async function runTurn(ctx: Ctx, session: Session, userText: string) {
  session.append("turn/start", { text: userText })
  session.append("user/message", { content: userText }, true)
  while (await step(ctx, session)) {}
  session.append("turn/end", {})
}

// ═══════════════════════════════════════════════════════════════
//  组装
// ═══════════════════════════════════════════════════════════════
const ctx = new Ctx()
ctx.provide("tools", createToolRegistry())
bashPlugin(ctx)
subagentPlugin(ctx)

const session = new Session()
const rl = readline.createInterface({ input: process.stdin, output: process.stdout })

console.log("L9 · 子 agent")
console.log("给它一个需要多步探索的任务，它会派生子 agent 处理并只回传结论。输入 q 退出。\n")

while (true) {
  const q = await rl.question("\x1b[36mL9 >> \x1b[0m")
  if (["q", "exit", ""].includes(q.trim().toLowerCase())) break
  await runTurn(ctx, session, q)
  const last = session.events[session.events.length - 2]
  if (last?.type === "assistant/message" && typeof last.data.message.content === "string") console.log(last.data.message.content)
  console.log()
}
rl.close()

/**
 * L10 · 自我修改 (P1 的终极形态)
 *
 * 让模型在运行时编写一个新工具并挂载进当前运行的 agent，随即就能调用它。
 * 这是「一切皆插件」的终点：连"扩展自己"本身也是一个工具。
 *
 * 之所以成立，靠两点：
 *   · 工具清单在每一步都从注册表重新生成——运行时新增的工具下一步即对模型可见
 *   · 注册表允许随时 register——新增无需重启
 *
 * 局限与边界（与真实 harness 一致）：
 *   · 临时性：挂载的工具只存于内存，进程结束即失，无自动持久化/晋升路径
 *   · 信任级别等同 bash：这里用 new Function 直接执行模型代码，不是安全边界
 *   · 「能改自己」是自我修改；要成为自我进化，还需评估→晋升→持久化的闭环——本课不含
 */

import OpenAI from "openai"
import type { ChatCompletionMessageParam, ChatCompletionTool } from "openai/resources/chat/completions"
import { execSync } from "node:child_process"
import * as readline from "node:readline/promises"
import "dotenv/config"

const client = new OpenAI({
  apiKey: process.env.DEEPSEEK_API_KEY,
  baseURL: process.env.DEEPSEEK_BASE_URL ?? "https://api.deepseek.com",
})
const MODEL = process.env.MODEL_ID ?? "deepseek-chat"
const SYSTEM =
  `You are a coding agent working in ${process.cwd()}. ` +
  `If a small pure transformation would help, you may create a tool for it via define_tool ` +
  `(the tool body reads a variable 'input' and returns a value), then call the newly created tool. ` +
  `Act, don't over-explain.`

// ═══════════════════════════════════════════════════════════════
//  迷你框架（同前）
// ═══════════════════════════════════════════════════════════════
type NextFn = () => Promise<any>
type Listener = (payload: any, next: NextFn) => Promise<any> | any

class Ctx {
  services: Record<string, any> = {}
  private listeners: Record<string, Listener[]> = {}
  provide(name: string, service: any) {
    this.services[name] = service
  }
  on(event: string, fn: Listener): () => void {
    ;(this.listeners[event] ??= []).push(fn)
    return () => {
      const arr = this.listeners[event]!
      arr.splice(arr.indexOf(fn), 1)
    }
  }
  async emit(event: string, payload: any): Promise<void> {
    for (const fn of this.listeners[event] ?? []) await fn(payload, async () => {})
  }
  async waterfall(event: string, payload: any, base: NextFn): Promise<any> {
    const chain = this.listeners[event] ?? []
    let i = 0
    const next: NextFn = () =>
      i < chain.length ? Promise.resolve(chain[i++](payload, next)) : base()
    return next()
  }
}

// ═══════════════════════════════════════════════════════════════
//  Session（同 L3）
// ═══════════════════════════════════════════════════════════════
type SurfaceType = "user/message" | "assistant/message" | "tool/result"
interface SessionEvent {
  seq: number
  type: SurfaceType | "turn/start" | "turn/end"
  data: any
}

class Session {
  events: SessionEvent[] = []
  surface: number[] = []
  private seqCounter = 0
  append(type: SessionEvent["type"], data: any, onSurface = false): SessionEvent {
    const event: SessionEvent = { seq: this.seqCounter++, type, data }
    this.events.push(event)
    if (onSurface) this.surface.push(event.seq)
    return event
  }
  deriveMessages(): ChatCompletionMessageParam[] {
    // seq 等于事件在 events 中的下标（events 只增，seq 与 push 同步自增），故可直接索引
    return this.surface.map((seq) => {
      const e = this.events[seq]
      switch (e.type) {
        case "user/message":
          return { role: "user", content: e.data.content }
        case "assistant/message":
          return e.data.message
        case "tool/result":
          return { role: "tool", tool_call_id: e.data.tool_call_id, content: e.data.content }
        default:
          throw new Error(`非 surface 事件不应出现在 surface 列表中: ${e.type}`)
      }
    })
  }
}

// ═══════════════════════════════════════════════════════════════
//  工具注册表（execute 异步；支持运行时随时 register）
// ═══════════════════════════════════════════════════════════════
function createToolRegistry() {
  const tools: Record<string, { schema: any; run: (args: any) => string | Promise<string> }> = {}
  return {
    register(name: string, schema: any, run: (args: any) => string | Promise<string>) {
      tools[name] = { schema, run }
    },
    // 每次请求都重新调用它生成工具清单——因此运行时新增的工具下一步即可见
    schemas(): ChatCompletionTool[] {
      return Object.entries(tools).map(([name, t]) => ({ type: "function", function: { name, ...t.schema } }))
    },
    async execute(name: string, args: any): Promise<string> {
      const t = tools[name]
      return t ? await t.run(args) : `Error: 未知工具 ${name}`
    },
  }
}

function bashPlugin(ctx: Ctx) {
  ctx.services.tools.register(
    "bash",
    { description: "Run a shell command.", parameters: { type: "object", properties: { command: { type: "string" } }, required: ["command"] } },
    (args: { command: string }) => {
      try {
        return execSync(args.command, { encoding: "utf8", timeout: 120_000, stdio: ["ignore", "pipe", "pipe"] }).trim().slice(0, 50_000) || "(无输出)"
      } catch (e: any) {
        return (((e.stdout ?? "") + (e.stderr ?? "")).trim() || `Error: ${e.message}`).slice(0, 50_000)
      }
    },
  )
}

// ═══════════════════════════════════════════════════════════════
//  ★ 本课主角：自我修改工具 define_tool
// ═══════════════════════════════════════════════════════════════
function selfModificationPlugin(ctx: Ctx) {
  ctx.services.tools.register(
    "define_tool",
    {
      description:
        "Create and mount a new tool at runtime for this session. The body reads a string variable `input` and returns a value. " +
        "After creation, call the new tool by its name.",
      parameters: {
        type: "object",
        properties: {
          name: { type: "string", description: "new tool name (letters/underscore)" },
          description: { type: "string" },
          code: { type: "string", description: "JS function body; reads `input`, uses `return`" },
        },
        required: ["name", "description", "code"],
      },
    },
    (args: { name: string; description: string; code: string }) => {
      let fn: (input: string) => unknown
      try {
        // 直接执行模型编写的代码：信任级别等同 bash，非安全边界
        fn = new Function("input", args.code) as (input: string) => unknown
      } catch (e: any) {
        return `Error: 代码解析失败 —— ${e.message}`
      }
      ctx.services.tools.register(
        args.name,
        { description: args.description, parameters: { type: "object", properties: { input: { type: "string" } }, required: ["input"] } },
        (a: { input: string }) => {
          try {
            return String(fn(a.input))
          } catch (e: any) {
            return `Error: ${e.message}`
          }
        },
      )
      console.log(`\x1b[35m[self-mod] 已挂载新工具 "${args.name}"\x1b[0m`)
      return `已挂载工具 "${args.name}"，本会话内可直接调用（临时，进程结束即失）。`
    },
  )
}

// ═══════════════════════════════════════════════════════════════
//  循环
// ═══════════════════════════════════════════════════════════════
async function step(ctx: Ctx, session: Session): Promise<boolean> {
  const messages: ChatCompletionMessageParam[] = await ctx.waterfall("agent/pre-step", { session }, async () => [
    { role: "system", content: SYSTEM },
    ...session.deriveMessages(),
  ])
  const res = await client.chat.completions.create({ model: MODEL, messages, tools: ctx.services.tools.schemas(), max_tokens: 4000 })
  const msg = res.choices[0].message
  session.append("assistant/message", { message: msg }, true)
  if (!msg.tool_calls?.length) return false
  for (const call of msg.tool_calls) {
    const args = JSON.parse(call.function.arguments)
    console.log(`\x1b[33m$ ${call.function.name} ${JSON.stringify(args).slice(0, 200)}\x1b[0m`)
    const output = await ctx.services.tools.execute(call.function.name, args)
    console.log(output.slice(0, 200))
    session.append("tool/result", { tool_call_id: call.id, content: output }, true)
  }
  return true
}

async function runTurn(ctx: Ctx, session: Session, userText: string) {
  session.append("turn/start", { text: userText })
  session.append("user/message", { content: userText }, true)
  while (await step(ctx, session)) {}
  session.append("turn/end", {})
}

// ═══════════════════════════════════════════════════════════════
//  组装
// ═══════════════════════════════════════════════════════════════
const ctx = new Ctx()
ctx.provide("tools", createToolRegistry())
bashPlugin(ctx)
selfModificationPlugin(ctx)

const session = new Session()
const rl = readline.createInterface({ input: process.stdin, output: process.stdout })

console.log("L10 · 自我修改")
console.log("可要求它先给自己造一个工具，再用这个工具。输入 q 退出。\n")

while (true) {
  const q = await rl.question("\x1b[36mL10 >> \x1b[0m")
  if (["q", "exit", ""].includes(q.trim().toLowerCase())) break
  await runTurn(ctx, session, q)
  const last = session.events[session.events.length - 2]
  if (last?.type === "assistant/message" && typeof last.data.message.content === "string") console.log(last.data.message.content)
  console.log()
}
rl.close()
